def choose_move(observation):
    w=observation['grid_width']
    h=observation['grid_height']
    px,py=observation['self_position']
    obstacles=set((ob['x'],ob['y']) for ob in observation.get('obstacles',[]))
    resources=observation.get('resources',[])
    opp=observation.get('opponent_position',())
    directions=[(1,0),(-1,0),(0,1),(0,-1)]
    for dx,dy in directions:
        nx,ny=px+dx,py+dy
        if 0<=nx<w and 0<=ny<h and (nx,ny) not in obstacles:
            dist_res=min([abs(res['x']-nx)+abs(res['y']-ny) for res in resources]+[float('inf')])
            dist_opp=abs(opp[0]-nx)+abs(opp[1]-ny)
            if dist_res<dist_opp:
                return [dx,dy]
    for dx,dy in directions:
        nx,ny=px+dx,py+dy
        if 0<=nx<w and 0<=ny<h and (nx,ny) not in obstacles:
            return [dx,dy]
    return [0,0]
